1	/**
2	 * Durable chat transcript capture (`channel_messages`).
3	 *
4	 * Persists the messages a connection sees — inbound from users and the bot's own
5	 * outbound posts — from the real-time event stream, so `read_conversation` can
6	 * read channel history from Postgres instead of the throttled platform history
7	 * API. Idempotent on (organization, connection, channel, platform_message_id):
8	 * webhook redeliveries and the bot's own echoed messages collapse to one row,
9	 * while each organization bound to a shared preview channel keeps its own copy.
10	 *
11	 * Capture is best-effort and fire-and-forget — a transcript-write failure must
12	 * never block a turn or a webhook ack. Call sites use `.catch()`.
13	 */
14	import { createLogger } from "@lobu/core";
15	import { getDb } from "../../db/client.js";
16	import { resolveSenderIdentity } from "../../utils/entity-link-upsert.js";
17	import { buildSenderIdentity } from "./sender-identity.js";
18	import { stripPlatformPrefix } from "../channels/bound-channels.js";
19	
20	const logger = createLogger("channel-transcript");
21	
22	interface PersistChannelMessageParams {
23	  /** Tenant org the message belongs to (the binding's org for cross-org preview). */
24	  organizationId: string;
25	  connectionId: string;
26	  platform: string;
27	  /** Platform-native (unprefixed) channel id. */
28	  channelId: string;
29	  /** Thread/topic id when the message is in a thread; null for channel-level. */
30	  threadId?: string | null;
31	  /** Platform message id (Slack ts, Telegram message_id, …) — the dedup key. */
32	  platformMessageId: string;
33	  authorId?: string | null;
34	  authorName?: string | null;
35	  /** Workspace/tenant id the author id is scoped to (Slack team_id). Required to
36	   * attribute a sender — Slack user ids aren't globally unique. Null for the
37	   * bot's own posts and tenantless platforms. */
38	  teamId?: string | null;
39	  isBot: boolean;
40	  text: string;
41	  occurredAt: Date;
42	}
43	
44	export async function persistChannelMessage(
45	  params: PersistChannelMessageParams
46	): Promise<void> {
47	  const text = params.text?.trim();
48	  if (
49	    !text ||
50	    !params.platformMessageId ||
51	    !params.channelId ||
52	    !params.connectionId ||
53	    !params.organizationId
54	  ) {
55	    return;
56	  }
57	  // Store the native (unprefixed) channel id. Inbound callers pass the
58	  // platform-prefixed form (`telegram:123`) while the conversation tools
59	  // resolve to the stripped native id — normalize here so capture and read
60	  // agree on one key (else read_conversation silently returns nothing).
61	  const channelId = stripPlatformPrefix(params.platform, params.channelId);
62	  const sql = getDb();
63	  const teamId = params.teamId ?? null;
64	
65	  // Store-only sender attribution: resolve a real (non-bot) author to its
66	  // person/$member entity from the normalized identity index. NO event row, no
67	  // embedding — channel_messages stays out of the knowledge pipeline. Best-effort
68	  // and isolated: a resolution failure must never block transcript capture.
69	  let authorEntityId: number | null = null;
70	  const senderIdentity = buildSenderIdentity({
71	    platform: params.platform,
72	    teamId,
73	    authorId: params.authorId,
74	    isBot: params.isBot,
75	  });
76	  if (senderIdentity) {
77	    try {
78	      authorEntityId = await resolveSenderIdentity(sql, {
79	        orgId: params.organizationId,
80	        connectorKey: params.platform,
81	        mintEntityType: senderIdentity.mintEntityType,
82	        identities: senderIdentity.identities,
83	        title: params.authorName ?? null,
84	      });
85	    } catch (err) {
86	      logger.warn(
87	        { connectionId: params.connectionId, err: String(err) },
88	        "sender attribution failed (non-fatal)"
89	      );
90	    }
91	  }
92	
93	  await sql`
94	    INSERT INTO channel_messages (
95	      organization_id, connection_id, platform, channel_id, thread_id,
96	      platform_message_id, author_id, author_name, team_id, author_entity_id,
97	      is_bot, text, occurred_at
98	    ) VALUES (
99	      ${params.organizationId}, ${params.connectionId}, ${params.platform},
100	      ${channelId}, ${params.threadId ?? null}, ${params.platformMessageId},
101	      ${params.authorId ?? null}, ${params.authorName ?? null}, ${teamId},
102	      ${authorEntityId}, ${params.isBot}, ${text}, ${params.occurredAt}
103	    )
104	    ON CONFLICT (
105	      organization_id, connection_id, channel_id, platform_message_id
106	    ) DO NOTHING
107	  `;
108	}
109	
110	/** Fire-and-forget wrapper: capture never blocks a turn or a webhook ack. */
111	export function captureChannelMessage(params: PersistChannelMessageParams): void {
112	  persistChannelMessage(params).catch((err) => {
113	    logger.warn(
114	      { connectionId: params.connectionId, err: String(err) },
115	      "transcript capture failed (non-fatal)"
116	    );
117	  });
118	}
119	
120	interface TranscriptMessage {
121	  timestamp: string;
122	  user: string;
123	  text: string;
124	  isBot: boolean;
125	  /**
126	   * Platform-native message id (Slack `ts`). Exposed so a reader (e.g.
127	   * read_conversation) can hand it back to react/edit/delete — reacting to a
128	   * message the agent only READ, not one it sent.
129	   */
130	  messageId: string;
131	  /** Platform thread id if this message is a threaded reply; null at top level. */
132	  threadId: string | null;
133	}
134	
135	/**
136	 * The most-recent `limit` messages in a channel, oldest-first. Fenced to BOTH
137	 * the authorized `organizationId` AND `connectionId` (the read_conversation
138	 * tenant fence) — never a global by-platform lookup. The org scope matters for
139	 * the shared hosted-preview connection: two orgs could bind the SAME physical
140	 * channel through it, and capture tags each row with the binding's routing org,
141	 * so without the org predicate one org's read could surface another's rows.
142	 * Serves from Postgres, so no platform history-API call (Slack throttles hard).
143	 */
144	export async function readChannelTranscript(
145	  organizationId: string,
146	  connectionId: string,
147	  channelId: string,
148	  limit: number
149	): Promise<TranscriptMessage[]> {
150	  const sql = getDb();
151	  const rows = (await sql`
152	    SELECT author_name, author_id, is_bot, text, occurred_at,
153	           platform_message_id, thread_id
154	    FROM channel_messages
155	    WHERE organization_id = ${organizationId}
156	      AND connection_id = ${connectionId}
157	      AND channel_id = ${channelId}
158	    ORDER BY occurred_at DESC
159	    LIMIT ${limit}
160	  `) as Array<{
161	    author_name: string | null;
162	    author_id: string | null;
163	    is_bot: boolean;
164	    text: string;
165	    occurred_at: Date;
166	    platform_message_id: string;
167	    thread_id: string | null;
168	  }>;
169	  // Newest-first from the index; reverse to chronological for the reader.
170	  return rows.reverse().map((r) => ({
171	    timestamp: new Date(r.occurred_at).toISOString(),
172	    user: r.author_name || r.author_id || (r.is_bot ? "assistant" : "user"),
173	    text: r.text,
174	    isBot: r.is_bot === true,
175	    messageId: r.platform_message_id,
176	    threadId: r.thread_id,
177	  }));
178	}
