291	  // every sibling workspace — but the one bot token is enterprise-wide and reads
292	  // every workspace's channels. Resolving by connection id gives us that token
293	  // for any `T…` we're graphing. Only slackinst- slugs are installs; a BYO slug
294	  // (`agentconn-…`) skips straight to the fallback below.
295	  const connSlug = runtimeConnectionIdToSlug(connectionId);
296	  const installById = connSlug.startsWith('slackinst-')
